<template><section class="social-page utility-page"><header class="utility-header"><button aria-label="뒤로" @click="router.back()">‹</button><h1>크레딧</h1></header><template v-if="wallet"><div class="wallet-balance"><span>보유 크레딧</span><strong>{{wallet.balance.toLocaleString()}} <small>C</small></strong></div><h2>충전하기</h2><p class="muted">{{wallet.testMode?'테스트 충전 · 실제 결제되지 않습니다.':'결제 서비스 준비 중입니다.'}}</p><div class="credit-products"><button v-for="n in [100,300,500]" :disabled="busy||!wallet.testMode" @click="selected=n;confirm.showModal()">{{n}} C<small>테스트 충전</small></button></div><h2>충전·사용내역</h2><p v-if="!wallet.entries.length" class="social-empty">아직 사용내역이 없어요.</p><article v-for="e in wallet.entries" :key="e.id" class="ledger"><div><strong>{{e.referenceKey?.startsWith('TEST_TOPUP:')?'테스트 충전':e.referenceKey?.startsWith('EXTRA:')?'추가 인연 열기':e.amount<0?'대화방 열기':'크레딧 지급'}}</strong><time>{{new Date(e.createdAt).toLocaleString('ko-KR')}}</time></div><b :class="{plus:e.amount>0}">{{e.amount>0?'+':''}}{{e.amount}} C</b></article><p v-if="wallet.entries.length===100" class="muted">최근 100건을 표시합니다.</p></template><p v-if="error" role="alert">{{error}}</p><p v-if="status" role="status">{{status}}</p><dialog ref="confirm" class="social-dialog" @cancel="busy&&$event.preventDefault()"><h2>{{selected}}크레딧 테스트 충전</h2><p>실제 결제 없이 테스트용 크레딧이 추가됩니다.</p><button :disabled="busy" @click="confirm.close()">취소</button><button class="primary" :disabled="busy" @click="topup">{{busy?'처리 중…':'충전하기'}}</button><p v-if="error" role="alert">{{error}}</p></dialog></section></template>
<script setup>import {ref,onMounted} from 'vue';import {useRouter} from 'vue-router';import api from '../../api/api';import {requestId} from '../../components/requestId';import {refreshBadges} from '../../components/notificationEvents';import '../../components/social.css';const router=useRouter(),wallet=ref(),error=ref(''),status=ref(''),busy=ref(false),confirm=ref(),selected=ref(100);let pending;onMounted(async()=>{try{wallet.value=(await api.get('/social/wallet')).data;}catch{error.value='크레딧을 불러오지 못했어요.';}});
async function topup(){if(busy.value)return;busy.value=true;error.value='';if(!pending||pending.amount!==selected.value)pending={amount:selected.value,requestId:requestId()};try{wallet.value=(await api.post('/social/wallet/test-topup',pending)).data;pending=null;confirm.value.close();status.value='테스트 크레딧이 충전됐어요.';refreshBadges();}catch(e){error.value=e.response?.data?.message||'충전 결과를 확인하지 못했어요. 다시 시도해도 중복 충전되지 않습니다.';}finally{busy.value=false;}}</script><style scoped>.wallet-balance{padding:28px;background:#fff1e8;border-radius:22px;margin-bottom:28px}.wallet-balance span{font-size:12px;color:#9a735e}.wallet-balance strong{display:block;font-size:36px;margin-top:12px;color:#af5f42}.wallet-balance small{font-size:20px}h2{font-size:16px;margin:28px 0 14px}.credit-products{display:flex;gap:8px}.credit-products button{flex:1;padding:18px 5px;font-weight:700}.credit-products small{display:block;font-size:10px;margin-top:10px;font-weight:400}.ledger{display:flex;align-items:center;justify-content:space-between;padding:18px 0;border-bottom:1px solid #eee}.ledger strong{font-size:13px}.ledger time{display:block;font-size:10px;color:#999;margin-top:6px}.ledger b{font-size:14px}.plus{color:#c96947}</style>
